// Client-side re-implementation of the trained sklearn pipeline's decision
// function AND the retention-intelligence explanation/recommendation layer,
// for the static GitHub Pages demo (which has no backend to call).
//
// The saved model is: ColumnTransformer(OneHotEncoder, StandardScaler) ->
// LogisticRegression. That whole pipeline reduces to one linear combination
// of 0/1 one-hot indicators and scaled numeric values, passed through a
// sigmoid — so this file evaluates exactly that, using the real fitted
// weights in model_params.js (generated by docs/export_model_params.py from
// the same models/churn_logistic_model.joblib the FastAPI backend loads).
// It is not a separate or re-trained model.
//
// This mirrors src/retention/explain.py and src/retention/recommendations.py
// term for term, condition for condition — see tests/test_docs_model_js.py,
// which runs this actual file through Node and diffs its output against the
// real Python pipeline so the two can't silently drift apart.

const TOP_N_DEFAULT = 5;

// Business-rule retention playbook — must match src/retention/recommendations.py.
// One entry per actionable feature; every other feature can still appear as a
// contextual signal (see analyzeCustomer) but never produces a suggested action.
const RETENTION_RULES = {
  Contract: {
    condition: (customer) => customer.Contract === "Month-to-month",
    action: "Offer an incentive to move to a longer-term contract",
  },
  TechSupport: {
    condition: (customer) => customer.TechSupport === "No",
    action: "Offer a free or discounted tech-support trial",
  },
  PaymentMethod: {
    condition: (customer) => customer.PaymentMethod === "Electronic check",
    action: "Offer an incentive to switch to automatic payment",
  },
  tenure: {
    condition: (customer) => Number(customer.tenure) < 12,
    action: "Place customer in an early-life retention or onboarding campaign",
  },
  // Deliberately excludes a customer already paying below-average charges —
  // see src/retention/recommendations.py for why.
  MonthlyCharges: {
    condition: (customer, means) => Number(customer.MonthlyCharges) > means.MonthlyCharges,
    action: "Review the customer's current plan, pricing, and bundle",
  },
  OnlineSecurity: {
    condition: (customer) => customer.OnlineSecurity === "No",
    action: "Consider an Online Security trial or bundled offer",
  },
  OnlineBackup: {
    condition: (customer) => customer.OnlineBackup === "No",
    action: "Consider an Online Backup trial or bundled offer",
  },
  DeviceProtection: {
    condition: (customer) => customer.DeviceProtection === "No",
    action: "Consider a Device Protection trial or bundled offer",
  },
};

function sigmoid(z) {
  return 1 / (1 + Math.exp(-z));
}

function getTrainingMeans(params) {
  const means = {};
  for (const term of params.terms) {
    if (term.type === "scaled") means[term.field] = term.mean;
  }
  return means;
}

function describeNumerical(field, value, mean) {
  const comparison = value < mean ? "below average" : "above average";
  if (field === "tenure") return `Tenure: ${value.toFixed(0)} months (${comparison})`;
  if (field === "MonthlyCharges") return `Monthly charges: $${value.toFixed(2)} (${comparison})`;
  if (field === "TotalCharges") return `Total charges: $${value.toFixed(2)} (${comparison})`;
  return `${field}: ${value.toFixed(2)} (${comparison})`;
}

// One row per transformed model term: base feature, readable explanation,
// and this customer's contribution (coefficient * transformed value).
// Zero-contribution one-hot terms (categories the customer doesn't have)
// are skipped, same as they'd never appear in the Python side's top-N lists.
function computeContributions(customer, params) {
  const rows = [];
  for (const term of params.terms) {
    if (term.type === "onehot") {
      if (String(customer[term.field]) !== String(term.value)) continue;
      rows.push({
        feature: term.field,
        explanation: `${term.field} = ${term.value}`,
        contribution: term.coef,
      });
    } else if (term.type === "scaled") {
      const value = Number(customer[term.field]);
      const contribution = ((value - term.mean) / term.scale) * term.coef;
      rows.push({
        feature: term.field,
        explanation: describeNumerical(term.field, value, term.mean),
        contribution,
      });
    }
  }
  return rows;
}

function isActionable(feature) {
  return Object.prototype.hasOwnProperty.call(RETENTION_RULES, feature);
}

function suggestAction(feature, customer, means) {
  const rule = RETENTION_RULES[feature];
  if (!rule) return null;
  return rule.condition(customer, means) ? rule.action : null;
}

function churnProbability(customer, params) {
  let z = params.intercept;
  for (const term of params.terms) {
    if (term.type === "onehot") {
      if (String(customer[term.field]) === String(term.value)) {
        z += term.coef;
      }
      // A category with no matching term (shouldn't happen from the <select>
      // inputs in index.html) contributes 0, mirroring OneHotEncoder's
      // handle_unknown="ignore" behavior in the real pipeline.
    } else if (term.type === "scaled") {
      const value = Number(customer[term.field]);
      z += ((value - term.mean) / term.scale) * term.coef;
    }
  }
  return sigmoid(z);
}

function riskCategory(probability, threshold, mediumCutoff) {
  if (probability >= mediumCutoff) return "High";
  if (probability >= threshold) return "Medium";
  return "Low";
}

// Full retention-intelligence result for one customer — same shape as the
// FastAPI /predict response (see api/schemas.py RetentionIntelligenceResponse).
function analyzeCustomer(customer, params, topN = TOP_N_DEFAULT) {
  const probability = churnProbability(customer, params);
  const prediction = probability >= params.threshold ? 1 : 0;
  const means = getTrainingMeans(params);

  const contributions = computeContributions(customer, params);
  const riskRows = contributions
    .filter((row) => row.contribution > 0)
    .sort((a, b) => b.contribution - a.contribution)
    .slice(0, topN);
  const protectiveRows = contributions
    .filter((row) => row.contribution < 0)
    .sort((a, b) => a.contribution - b.contribution)
    .slice(0, topN);

  const toDriver = (row) => ({ ...row, actionable: isActionable(row.feature) });

  const suggestedActions = [];
  for (const row of riskRows) {
    const action = suggestAction(row.feature, customer, means);
    if (action) suggestedActions.push({ driver: row.explanation, action });
  }

  return {
    churn_probability: probability,
    prediction,
    label: prediction === 1 ? "Likely to Churn" : "Likely to Stay",
    threshold: params.threshold,
    risk_category: riskCategory(probability, params.threshold, params.medium_risk_cutoff),
    risk_drivers: riskRows.map(toDriver),
    protective_factors: protectiveRows.map(toDriver),
    suggested_actions: suggestedActions,
  };
}

// Kept for backward compatibility with earlier callers that only need the
// churn prediction itself; analyzeCustomer() returns the same fields plus
// the explanation/recommendation layer.
function predictChurn(customer, params) {
  const result = analyzeCustomer(customer, params);
  return {
    churn_probability: result.churn_probability,
    prediction: result.prediction,
    label: result.label,
    threshold: result.threshold,
    risk_category: result.risk_category,
  };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    churnProbability,
    predictChurn,
    analyzeCustomer,
    riskCategory,
    sigmoid,
    isActionable,
    suggestAction,
  };
}
